const DEPTH_PROGRAM: &str = r#"(progn
  (require 'cl-lib)
  (defvar neovm--sl-count 0)
  (defun neovm--sl-opt (n &optional unused)
    (setq neovm--sl-count (1+ neovm--sl-count))
    (if (= n 0) 0 (1+ (neovm--sl-opt (1- n)))))
  (defun neovm--sl-rest (n &rest unused)
    (setq neovm--sl-count (1+ neovm--sl-count))
    (if (= n 0) 0 (1+ (neovm--sl-rest (1- n) n))))
  (defun neovm--sl-constant (n)
    (cl-flet ((local (x)
               (setq neovm--sl-count (1+ neovm--sl-count))
               (if (= x 0) 0 (1+ (neovm--sl-constant (1- x))))))
      (prog1 (local n) (local 0))))
  (dolist (f '(neovm--sl-opt neovm--sl-rest neovm--sl-constant)) (byte-compile f))
  (dotimes (_ 60) (neovm--sl-opt 60) (neovm--sl-rest 60) (neovm--sl-constant 60)))"#;

macro_rules! depth_observation {
    ($callee:literal) => {
        concat!(
            r#"(list (let ((max-lisp-eval-depth 300))
                (setq neovm--sl-count 0)
                (list (condition-case err ("#,
            $callee,
            r#" 1000) (error err))
                      (> neovm--sl-count 100) (< neovm--sl-count 300)))
                  ("#,
            $callee,
            r#" 20))"#
        )
    };
}

