const REDEFINE_PROGRAM: &str = r#"(progn
  (require 'cl-lib)
  (defvar neovm--sx-arm nil)
  (defvar neovm--sx-live nil)
  (defvar neovm--sx-keys (make-hash-table :test 'eq :weakness 'key))
  (defun neovm--sx-opt (n x &optional unused)
    (if (= n 0)
        (if neovm--sx-arm
            (progn (fset 'neovm--sx-opt (lambda (&rest _) 'new))
                   (garbage-collect)
                   (setq neovm--sx-live (hash-table-count neovm--sx-keys))
                   (+ (car x) 0.5)) 0)
      (1+ (neovm--sx-opt (1- n) x))))
  (defun neovm--sx-opt-caller (n x) (neovm--sx-opt n x))
  (defun neovm--sx-rest (n &rest x)
    (if (= n 0)
        (if neovm--sx-arm
            (progn (fset 'neovm--sx-rest (lambda (&rest _) 'new))
                   (garbage-collect)
                   (setq neovm--sx-live (hash-table-count neovm--sx-keys))
                   (+ (car x) 0.5)) 0)
      (1+ (neovm--sx-rest (1- n) (car x)))))
  (defun neovm--sx-rest-caller (n x) (neovm--sx-rest n x))
  (defun neovm--sx-constant-caller (x)
    (cl-flet ((local (y)
               (if neovm--sx-arm
                   (progn (fset 'neovm--sx-constant-caller (lambda (_) 'new))
                          (garbage-collect)
                          (setq neovm--sx-live (hash-table-count neovm--sx-keys))
                          (+ (car y) 0.5)) 0)))
      (list (1+ (local x)) (1+ (local x)))))
  (dolist (f '(neovm--sx-opt neovm--sx-opt-caller neovm--sx-rest
               neovm--sx-rest-caller neovm--sx-constant-caller)) (byte-compile f))
  (dotimes (i neovm--dc-warm)
    (neovm--sx-opt-caller 3 '(1)) (neovm--sx-rest-caller 3 1)
    (neovm--sx-constant-caller '(1))))"#;

#[test]
fn gnu_optional_redefinition_and_gc_resume_the_entered_old_object() {
    let runs = assert_gnu_shape(
        "optional-redefine",
        "optional",
        REDEFINE_PROGRAM,
        r#"(progn (puthash (symbol-function 'neovm--sx-opt) t neovm--sx-keys)
          (list (let ((neovm--sx-arm t)) (neovm--sx-opt-caller 3 '(40)))
                neovm--sx-live (neovm--sx-opt-caller 3 '(1))))"#,
        include_str!("direct_call_shape_parity/optional-redefine.expect"),
        true,
    );
    assert!(runs[2].cold_exits > 0, "old optional activation deopts");
}

#[test]
fn gnu_rest_redefinition_and_gc_resume_the_entered_old_object() {
    let runs = assert_gnu_shape(
        "rest-redefine",
        "rest",
        REDEFINE_PROGRAM,
        r#"(progn (puthash (symbol-function 'neovm--sx-rest) t neovm--sx-keys)
          (list (let ((neovm--sx-arm t)) (neovm--sx-rest-caller 3 40))
                neovm--sx-live (neovm--sx-rest-caller 3 1)))"#,
        include_str!("direct_call_shape_parity/rest-redefine.expect"),
        true,
    );
    assert!(runs[2].cold_exits > 0, "old rest activation deopts");
}

#[test]
fn gnu_constant_redefinition_and_gc_resume_the_entered_old_object() {
    let runs = assert_gnu_shape(
        "constant-redefine",
        "constant",
        REDEFINE_PROGRAM,
        r#"(progn
          (dolist (c (append (aref (symbol-function 'neovm--sx-constant-caller) 2) nil))
            (when (byte-code-function-p c) (puthash c t neovm--sx-keys)))
          (list (let ((neovm--sx-arm t)) (neovm--sx-constant-caller '(40)))
                neovm--sx-live (neovm--sx-constant-caller '(1))))"#,
        include_str!("direct_call_shape_parity/constant-redefine.expect"),
        false,
    );
    assert!(runs[2].cold_exits > 0, "old constant activation deopts");
}
